window.jQuery||document.writeln('<script src = "static/jquery-3.5.1.min.js">');var buttonColors=["red","blue","green","yellow"];var level=1;var generatedSequence=[];var userSeqIndx=0;var hasGameEnded=true;var winningTexts=["Keep going! 🎉","Amazing!🔥","Champion vibes! 🏆","Incredible!🌟","You're unstoppable! 🚀","Fantastic! 💫","Great job! 👏","Superb! 🌈","You're a star! ⭐","Outstanding! 🥇","Bravo! 🎊","Legendary! 🐾"];var wrongAudio=new Audio("./sounds/wrong.mp3");var winningTextIndex=0;function cycleQuotes(){if(++winningTextIndex+1>winningTexts.length){winningTextIndex=0}return winningTexts[winningTextIndex]}function addNewColor(){generatedSequence.push(buttonColors[randomNumber()])}function randomNumber(){var random=parseInt(Math.random()*4);if(random>=4){randomException()}function randomException(){random=parseInt(Math.random()*4);if(random>=4){randomException()}}return random}async function animateSequence(){if(!hasGameEnded){for(var i=0;i<generatedSequence.length;i++){var audio=new Audio(`./sounds/${generatedSequence[i]}.mp3`);audio.play().then((function(){audio.remove()}));await $("#"+generatedSequence[i]).animate({opacity:.3}).animate({opacity:1}).promise()}}}async function levelHandler(){if(!hasGameEnded){addNewColor();await animateSequence();checkSequence()}}async function checkSequence(){$(".btn").on("click",(function(event){var button=$(this);var audio=new Audio(`./sounds/${this.id}.mp3`);audio.play().then((function(){audio.remove()}));button.addClass("pressed");button.animate({opacity:.3}).animate({opacity:1}).promise();setTimeout((function(){button.removeClass("pressed")}),200);if(userSeqIndx+1==generatedSequence.length){if(this.id!=generatedSequence[userSeqIndx++]){gameLost();return false}setTimeout((function(){nextLevel()}),1e3);return true}else if(userSeqIndx<generatedSequence.length){if(this.id!=generatedSequence[userSeqIndx++]){gameLost();return false}}else{gameLost();return false}}))}function gameLost(){$("#level-title").text("Aw cutie, you lost! Wanna marry me?💐 Press A.");wrongAudio.play();generatedSequence=[];hasGameEnded=true;$(".btn").off("click")}function nextLevel(){$("#level-title").text(winningTexts[randomNumber()]);level++;userSeqIndx=0;levelHandler();$(".btn").off("click")}function startGame(){level=1;hasGameEnded=false;levelHandler()}$(document).on("click",(function(){if(hasGameEnded){startGame();$("#level-title").text("Game On!")}}));$(document).on("keydown",(function(event){if(event.key.toLowerCase()=="a"&&hasGameEnded){startGame();$("#level-title").text("Game On!")}}));